문10. 다음C 언어프로그램의출력결과는?
#include <stdio.h>
#define SWAP(x, y, t) ((t)=(x), (x)=(y), (y)=(t))
void recursive(char *list, int i, int n) {
int j, temp;
if (i == n) {
for (j = 0 ; j <= n ; j++)
printf("%c", list[j]);
printf(" ");
}
else {
for (j = i ; j <= n ; j++) {
SWAP(list[i], list[j], temp);
recursive(list, i + 1, n);
SWAP(list[i], list[j], temp);
}
}
}
int main()
{
char list[3] = {'a', 'b', 'c'};
recursive(list, 0, 2);
}
①ab ac bc
②ab bc ca
③abc acb bac bca cba cab
④abc acb bca bac cab cba

문18. 다음C 언어프로그램의출력결과는?
#include <stdio.h>
void func(char s[], int size) {
if (size <= 0)
return;
s[size-1] = s[size-1] + 1;
func(s,size-2);
}
int main()
{
char str[] = "window";
func(str, 6);
printf("%c", str[3]);
}
①d
②e
③n
④o

